contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 recordedBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(this).balance;
        uint256 cBalanceBefore = address(c).balance;

        bool reverted = false;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 recordedAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(this).balance;
        uint256 cBalanceAfter = address(c).balance;

        assert((reverted && recordedAfter == recordedBefore && balanceAfter == balanceBefore && cBalanceAfter == cBalanceBefore) || (!reverted && recordedAfter == 0 && balanceAfter == balanceBefore + recordedBefore && cBalanceAfter == cBalanceBefore - recordedBefore));
    }

    receive() external payable {}
}

