import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.addToBalance{value: depositAmount}() {} catch { return; }
        uint256 recordedBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        uint256 balanceBefore = address(this).balance;
        uint256 cBalanceBefore = address(c).balance;
        bool reverted = false;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 recordedAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { recordedAfter = __r; } catch { return; }
        uint256 balanceAfter = address(this).balance;
        uint256 cBalanceAfter = address(c).balance;
        assertTrue((reverted && recordedAfter == recordedBefore && balanceAfter == balanceBefore && cBalanceAfter == cBalanceBefore) || (!reverted && recordedAfter == 0 && balanceAfter == balanceBefore + recordedBefore && cBalanceAfter == cBalanceBefore - recordedBefore));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
